// The Drive file id out of the share notice.
//
// Google sends these as HTML with the link in a few places; the id is the one
// stable thing in all of them. Anything without one is not a workbook share and
// is dropped rather than guessed at.
const out = [];

for (const item of $input.all()) {
  const mail = item.json;
  const body = [mail.html, mail.textPlain, mail.snippet, mail.subject]
    .filter(Boolean).join('\n');

  const m = body.match(/\/spreadsheets\/d\/([A-Za-z0-9_-]{20,})/)
         || body.match(/\/file\/d\/([A-Za-z0-9_-]{20,})/)
         || body.match(/[?&]id=([A-Za-z0-9_-]{20,})/);

  if (!m) continue;

  out.push({
    json: {
      fileId: m[1],
      subject: mail.subject || '',
      from: mail.from || '',
      messageId: mail.id,
      receivedAt: mail.date || new Date().toISOString(),
    },
  });
}

return out;

// One item per file, so the commits below can run over them.
const d = $input.first().json;
return Object.entries(d.contents).map(([path, content]) => ({
  json: {
    path,
    content,
    name: d.name,
    slug: d.slug,
    figuresChecked: d.figuresChecked,
    tabs: d.tabs,
  },
}));

